using System;using Ossastra.CharacterCore;
class PresentationTests{static void Main(){var type=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.ActionPresentationPolicy");if(type==null)throw new Exception("missing explicit recovery presentation policy");var m=type.GetMethod("RetainMainPose");bool Read(bool active,bool moveReady,bool moving)=>(bool)m.Invoke(null,new object[]{active,moveReady,moving});if(!Read(true,false,true))throw new Exception("windup must retain pose");if(Read(true,true,true))throw new Exception("moving recovery must yield pose");if(!Read(true,true,false))throw new Exception("idle recovery should finish pose");if(Read(false,true,false))throw new Exception("inactive has no action pose");Console.WriteLine("4 presentation contracts passed");}}
